#[test]
fn max_message_bytes_attribute() {
    use serde_json::json;
    let mut h = common::Harness::new();
    let r = h.ok(json!({"Command":"CreateQueue","QueueName":"q"}));
    let _ = r;
    let a = h.ok(json!({"Command":"GetQueueAttributes","QueueName":"q"}));
    assert_eq!(a["Attributes"]["MaxMessageBytes"], 1024);
    for bad in [json!(0), json!(1025), json!("5"), json!(5.0)] {
        assert_eq!(
            h.err(json!({"Command":"SetQueueAttributes","QueueName":"q","Attributes":{"MaxMessageBytes":bad}})),
            "InvalidParameterValue"
        );
    }
    h.ok(json!({"Command":"CreateQueue","QueueName":"s","Attributes":{"MaxMessageBytes":4}}));
    // differing MaxMessageBytes takes part in CreateQueue rule 4
    assert_eq!(
        h.err(json!({"Command":"CreateQueue","QueueName":"s"})),
        "QueueAlreadyExists"
    );
    h.ok(json!({"Command":"CreateQueue","QueueName":"s","Attributes":{"MaxMessageBytes":4}}));
    h.ok(json!({"Command":"SendMessage","QueueName":"s","Body":"abcd"}));
    // 2 characters, 4 bytes: allowed; 5 bytes: not
    h.ok(json!({"Command":"SendMessage","QueueName":"s","Body":"éé"}));
    assert_eq!(
        h.err(json!({"Command":"SendMessage","QueueName":"s","Body":"abcde"})),
        "InvalidParameterValue"
    );
    // lowering it leaves existing messages alone; raising allows more
    h.ok(json!({"Command":"SetQueueAttributes","QueueName":"s","Attributes":{"MaxMessageBytes":1}}));
    let c = h.ok(json!({"Command":"GetQueueAttributes","QueueName":"s"}));
    assert_eq!(c["Counts"]["Visible"], 2);
    assert_eq!(
        h.err(json!({"Command":"SendMessage","QueueName":"s","Body":"ab"})),
        "InvalidParameterValue"
    );
    // it comes before the FIFO/standard rules (rule 0)
    assert_eq!(
        h.err(json!({"Command":"SendMessage","QueueName":"s","Body":"ab","GroupId":"g"})),
        "InvalidParameterValue"
    );
    // a missing queue still wins
    assert_eq!(
        h.err(json!({"Command":"SendMessage","QueueName":"nope","Body":"ab"})),
        "QueueDoesNotExist"
    );
}

